import{_ as o,o as t,c as r,a6 as a}from"./chunks/framework.QBF2cGGQ.js";const c=JSON.parse('{"title":"02 · Prompt 与上下文工程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/02-prompt-context.md","filePath":"guide/02-prompt-context.md","lastUpdated":1793327470000}'),i={name:"guide/02-prompt-context.md"};function n(p,s,l,e,u,g){return t(),r("div",null,[...s[0]||(s[0]=[a('<h1 id="_02-·-prompt-与上下文工程" tabindex="-1">02 · Prompt 与上下文工程 <a class="header-anchor" href="#_02-·-prompt-与上下文工程" aria-label="Permalink to &quot;02 · Prompt 与上下文工程&quot;">​</a></h1><blockquote><p><strong>投入权重：10%</strong> · 这一层的正确名字是「上下文工程」——你控制的不只是措辞，是整个输入的信息结构。 别学成&quot;咒语大全&quot;，那是玄学不是工程。</p></blockquote><h2 id="为什么改名" tabindex="-1">为什么改名 <a class="header-anchor" href="#为什么改名" aria-label="Permalink to &quot;为什么改名&quot;">​</a></h2><p>2024 年大家说 Prompt Engineering，2025 年之后更准确的说法是 Context Engineering。区别在于：前者以为关键是&quot;怎么说话&quot;，后者认为关键是&quot;往窗口里放什么、按什么顺序放、放多少&quot;。同一个模型，换一种上下文组织方式，效果差异可以远大于换一个更贵的模型。这个认知转变很重要，因为它把&quot;调 prompt&quot;从玄学变成了可设计的工程问题。</p><h2 id="结构化" tabindex="-1">结构化 <a class="header-anchor" href="#结构化" aria-label="Permalink to &quot;结构化&quot;">​</a></h2><ul><li><strong>Prompt 的本质</strong> <span class="prio prio-must">必须</span> — 不是&quot;命令&quot;，是给条件概率施加约束。所有技巧的本质都是&quot;减少模型猜错的空间&quot;。</li><li><strong>六要素结构</strong> <span class="prio prio-must">必须</span> — 角色 / 任务 / 上下文 / 约束 / 输出格式 / 示例。缺哪个补哪个，比堆形容词有效得多。</li><li><strong>System 与 User 的分工</strong> <span class="prio prio-must">必须</span> — 稳定规则进 system（可缓存、更省钱），变量进 user。混着写会导致前缀缓存失效，成本直接翻倍。</li><li><strong>指令的具体性</strong> <span class="prio prio-must">必须</span> — &quot;简洁一点&quot;是废话，&quot;不超过 3 句话，每句不超过 30 字&quot;才可执行。凡是无法判断&quot;做到没做到&quot;的要求，都要改写。</li><li><strong>负面指令的陷阱</strong> <span class="prio prio-must">必须</span> — &quot;不要做 X&quot;经常适得其反（提到即激活）。改成&quot;应该做 Y&quot;。</li><li><strong>分隔符与结构化标记</strong> <span class="prio prio-must">必须</span> — 用 XML 标签或 Markdown 分隔不同来源的内容，能显著降低混淆与注入风险。</li><li><strong>信息顺序的影响</strong> <span class="prio prio-imp">重要</span> — 首尾位置权重更高。把最重要的约束放最后（近因效应），或首尾各放一次。</li><li><strong>冗余与自相矛盾</strong> <span class="prio prio-imp">重要</span> — 长 prompt 里前后矛盾是常见 bug。写完后专门做一次&quot;冲突检查&quot;。</li></ul><h2 id="推理范式" tabindex="-1">推理范式 <a class="header-anchor" href="#推理范式" aria-label="Permalink to &quot;推理范式&quot;">​</a></h2><ul><li><strong>Few-shot 示例设计</strong> <span class="prio prio-must">必须</span> — 示例要覆盖边界情况，不只是典型情况。示例顺序会影响结果（近因效应），重要示例放后面。</li><li><strong>CoT 思维链</strong> <span class="prio prio-must">必须</span> — 让模型先写推理再给结论，对多步任务提升明显；简单任务上反而增加成本与出错面。</li><li><strong>Zero-shot CoT</strong> <span class="prio prio-imp">重要</span> — &quot;让我们一步步思考&quot;这类触发语。在新一代推理模型上收益已明显下降，别迷信旧教程。</li><li><strong>Self-Consistency</strong> <span class="prio prio-imp">重要</span> — 多次采样取多数投票。提升准确率，成本线性上升，适合高价值低并发场景。</li><li><strong>ReAct</strong> <span class="prio prio-must">必须</span> — 思考-行动-观察循环，Agent 的基础范式，第 04 章详述。</li><li><strong>Reflexion 自我反思</strong> <span class="prio prio-imp">重要</span> — 失败后分析原因再重试。要有明确的失败信号才有用，否则只是重复犯错。</li><li><strong>Least-to-Most</strong> <span class="prio prio-opt">选学</span> — 把复杂问题拆成子问题依次解决。</li><li><strong>角色扮演的作用与边界</strong> <span class="prio prio-imp">重要</span> — 能改变语气与知识调用倾向，但不增加模型不具备的能力。别指望&quot;你是资深律师&quot;就真变律师。</li></ul><h2 id="输出约束" tabindex="-1">输出约束 <a class="header-anchor" href="#输出约束" aria-label="Permalink to &quot;输出约束&quot;">​</a></h2><ul><li><strong>JSON 输出与 Schema 设计</strong> <span class="prio prio-must">必须</span> — 字段少、嵌套浅、给枚举值。嵌套三层以上的 schema 出错率会明显上升。</li><li><strong>JSON Mode / Structured Output</strong> <span class="prio prio-must">必须</span> — 厂商级的结构化输出保证，比在 prompt 里求&quot;请输出 JSON&quot;可靠一个数量级。</li><li><strong>Function Calling 作为输出约束</strong> <span class="prio prio-must">必须</span> — 本质是&quot;强制模型填参数&quot;，比让它自由写 JSON 更稳。也可用来做分类器（枚举值就是类别）。</li><li><strong>Grammar-constrained decoding</strong> <span class="prio prio-imp">重要</span> — GBNF / Outlines / JSON Schema 级约束，本地部署时能做到 100% 合法输出。</li><li><strong>输出解析与容错</strong> <span class="prio prio-must">必须</span> — 永远不要假设模型输出一定合法。写重试、修复、降级三条路径。</li><li><strong>长度控制</strong> <span class="prio prio-imp">重要</span> — 用 max_tokens 硬约束 + prompt 软引导，双保险。</li><li><strong>流式输出的解析难点</strong> <span class="prio prio-imp">重要</span> — 结构化输出在流式时是&quot;半截 JSON&quot;，必须用增量解析器，不能等收完再 parse。</li></ul><h2 id="模板与版本" tabindex="-1">模板与版本 <a class="header-anchor" href="#模板与版本" aria-label="Permalink to &quot;模板与版本&quot;">​</a></h2><ul><li><strong>模板化与变量注入</strong> <span class="prio prio-must">必须</span> — 模板与代码分离，变量显式声明。避免字符串拼接导致注入。</li><li><strong>Prompt 版本管理</strong> <span class="prio prio-must">必须</span> — 每次改动留版本号与改动理由，能回滚。用 git 管，别在代码里硬编码。</li><li><strong>Prompt 的 A/B 测试</strong> <span class="prio prio-must">必须</span> — 同一批测试集跑两个版本，看指标差异。没有 A/B 的&quot;我觉得更好了&quot;都是错觉。</li><li><strong>Prompt 与模型版本绑定</strong> <span class="prio prio-must">必须</span> — 换模型必须重跑全部评测。同一个 prompt 在新模型上可能显著变差，这不是模型变笨，是分布变了。</li><li><strong>Prompt 的复用与组合</strong> <span class="prio prio-imp">重要</span> — 把 prompt 拆成可复用片段（人格/格式/安全规则），按需拼装，而不是每个场景抄一份。</li></ul><h2 id="注入攻防" tabindex="-1">注入攻防 <a class="header-anchor" href="#注入攻防" aria-label="Permalink to &quot;注入攻防&quot;">​</a></h2><ul><li><strong>直接提示注入</strong> <span class="prio prio-must">必须</span> — 用户输入&quot;忽略以上指令&quot;。防御靠分层与输出校验，不靠措辞。</li><li><strong>间接提示注入</strong> <span class="prio prio-must">必须</span> — 恶意内容藏在检索文档、网页、工具返回值里。这是 RAG 与 Agent 的最大安全风险，也是最容易被忽视的。</li><li><strong>系统提示词泄露</strong> <span class="prio prio-must">必须</span> — 用户诱导模型复述 system prompt。敏感规则不要写在 prompt 里。</li><li><strong>防御策略</strong> <span class="prio prio-must">必须</span> — 内容与指令分区、工具白名单、输出侧二次校验、最小权限。没有单一银弹，必须叠层。</li><li><strong>越狱的持续性</strong> <span class="prio prio-imp">重要</span> — 这是持续对抗，不是一次性修复。要有红队用例库并定期更新。</li></ul><h2 id="上下文工程" tabindex="-1">上下文工程 <a class="header-anchor" href="#上下文工程" aria-label="Permalink to &quot;上下文工程&quot;">​</a></h2><ul><li><strong>Context Engineering 概念</strong> <span class="prio prio-must">必须</span> — 比 prompt engineering 更准确：管理进入上下文窗口的全部信息（指令 / 知识 / 历史 / 工具结果）。</li><li><strong>上下文压缩</strong> <span class="prio prio-must">必须</span> — 摘要历史、LLMLingua 类压缩、只保留结构化结论。长对话必须做，否则成本失控。</li><li><strong>上下文污染</strong> <span class="prio prio-must">必须</span> — 错误信息进入上下文后被反复引用放大。需要&quot;事实核对点&quot;和清理机制。</li><li><strong>上下文隔离</strong> <span class="prio prio-imp">重要</span> — 多 Agent 各自独立上下文，只交换结构化结论，避免互相污染。</li><li><strong>动态上下文组装</strong> <span class="prio prio-must">必须</span> — 按任务类型决定塞什么，而不是固定模板。这是产品级与 demo 级的分界。</li><li><strong>上下文的最小充分原则</strong> <span class="prio prio-imp">重要</span> — 够用就停。塞满窗口不会更好，只会更贵更慢更容易迷失。</li></ul>',16)])])}const q=o(i,[["render",n]]);export{c as __pageData,q as default};
